{"command": "cd /tmp && for b in vul fix; do 
addr=$(r2 -2 -q -c '/ is normal file, but there are file paths' /out-$b/kimgio_fuzzer 2>/dev/null | awk '{print $1}');
echo "=== $b string@$addr ===";
r2 -2 -q -c "aa; /r $addr" /out-$b/kimgio_fuzzer 2>/dev/null | head;
done"}

